{"code": "def check_domain():
    import math

    # Test points in different intervals
    test_points = [-10, 0, 1, 2, 2.5, 3, 4, 10]

    valid_points = []
    invalid_points = []

    for x in test_points:
        try:
            val = x**2 - 5*x + 6
            if val > 0:
                # Calculate function value
                f_val = (2*x - 7) / math.sqrt(val)
                valid_points.append((x, f_val))
            else:
                invalid_points.append((x, val))
        except ValueError:
            invalid_points.append((x, "sqrt of negative"))
        except ZeroDivisionError:
            invalid_points.append((x, "division by zero"))

    return valid_points, invalid_points

print(check_domain())"}

